export default function ({ text }) {
  if (typeof text !== "string") throw Error("Missing CSV text");
  text = text.replace(/^\uFEFF/, "");
  let rows = [],
    row = [],
    cell = "",
    quoted = false,
    closed = false;
  for (let i = 0; i < text.length; i++) {
    let c = text[i];
    if (quoted) {
      if (c === '"' && text[i + 1] === '"') {
        cell += '"';
        i++;
      } else if (c === '"') {
        quoted = false;
        closed = true;
      } else cell += c;
    } else if (closed && c !== "," && c !== "\n" && c !== "\r")
      throw Error("Invalid CSV after closing quote");
    else if (c === '"') {
      if (cell) throw Error("Invalid CSV quote");
      quoted = true;
    } else if (c === ",") {
      row.push(cell);
      cell = "";
      closed = false;
    } else if (c === "\n") {
      row.push(cell);
      rows.push(row);
      row = [];
      cell = "";
      closed = false;
    } else if (c !== "\r") cell += c;
  }
  if (quoted) throw Error("Unclosed CSV quote");
  if (cell || row.length) {
    row.push(cell);
    rows.push(row);
  }
  if (
    !rows.length ||
    !rows[0].length ||
    rows[0].some((x) => !x) ||
    new Set(rows[0]).size !== rows[0].length ||
    rows.some((r) => r.length !== rows[0].length)
  )
    throw Error("Invalid CSV rows or headers");
  return { table: rows, sample: JSON.stringify({ headers: rows[0], rows: rows.slice(1, 3) }) };
}

