export default function ({ table, result }) {
  const columns = result?.columns;
  if (
    !Array.isArray(columns) ||
    columns.some((x) => typeof x !== "string" || !table[0].includes(x))
  )
    throw Error("Model returned unknown column names");
  const remove = new Set(columns),
    keep = table[0].map((x, i) => (remove.has(x) ? -1 : i)).filter((i) => i >= 0);
  if (!keep.length) throw Error("All columns identified; review before exporting");
  const esc = (x) => (/[",\r\n]/.test(x) ? '"' + x.replace(/"/g, '""') + '"' : x);
  return { csv: table.map((row) => keep.map((i) => esc(row[i])).join(",")).join("\n") + "\n" };
}

