export default async function ({ id, name, csv }, ctx) {
  const key = "pii-csv:" + id,
    s = await ctx.state.get(key);
  if (s?.status === "pending") throw Error("Inspect destination before retrying unknown upload");
  if (s?.status === "done") return { key, skip: true, name: "processed.csv", csv };
  await ctx.state.set(key, { status: "pending" });
  return {
    key,
    skip: false,
    name: (name.replace(/\.csv$/i, "") || "file") + "-" + id + "-review.csv",
    csv,
  };
}

